/* MOTORHAUS — a tiny dealership sim. Everything is saved locally. */
const $ = (s, r=document) => r.querySelector(s);
const $$ = (s, r=document) => [...r.querySelectorAll(s)];
const money = n => '$' + Math.round(n).toLocaleString('en-US');
const clamp = (n,a,b) => Math.max(a,Math.min(b,n));
const weekdays = ['MON','TUE','WED','THU','FRI','SAT','SUN'];
const carSeed = [
  {name:'Cobalt Sprint',year:2017,make:'Cobalt',model:'Sprint',type:'HATCHBACK',price:7800,value:11200,miles:84200,condition:78,color:'#8aa2a0',seller:'Mia Collins',risk:8,engine:73,body:81,clean:62},
  {name:'Veloce GT',year:2015,make:'Veloce',model:'GT',type:'COUPE',price:15700,value:22400,miles:61700,condition:72,color:'#c65e4d',seller:'Rico Alvarez',risk:14,engine:70,body:68,clean:74},
  {name:'Northstar LX',year:2019,make:'Northstar',model:'LX',type:'SUV',price:18600,value:25100,miles:49200,condition:88,color:'#8c927d',seller:'June Park',risk:5,engine:89,body:91,clean:81},
  {name:'Falcon RS',year:2014,make:'Falcon',model:'RS',type:'SPORT',price:21300,value:30500,miles:72800,condition:63,color:'#d39a43',seller:'Dale Mercer',risk:25,engine:59,body:61,clean:69},
  {name:'Metro 1.6',year:2016,make:'Metro',model:'1.6',type:'SEDAN',price:6200,value:9700,miles:106300,condition:58,color:'#6379a0',seller:'Nora Bell',risk:11,engine:55,body:67,clean:48},
  {name:'Aurelia S',year:2021,make:'Aurelia',model:'S',type:'LUXURY',price:36400,value:48200,miles:28300,condition:93,color:'#62776b',seller:'Victor Lane',risk:35,engine:95,body:94,clean:92}
];
const freshCar = (t,i) => ({...t,id:'m'+Date.now().toString(36)+Math.random().toString(36).slice(2,5),condition:t.condition,engine:t.engine,body:t.body,clean:t.clean,reported:false,listed:false,ask:0,mods:[],source:i%2?'Street seller':'City market'});
function newMarket(){return carSeed.map((t,i)=>{let c=freshCar(t,i);let swing=0.94+Math.random()*.13;c.price=Math.round(t.price*swing/100)*100;c.risk=clamp(t.risk+Math.round(Math.random()*10-5),3,55);return c})}
const defaultState=()=>({cash:32000,day:1,rep:12,inventory:[],market:newMarket(),activity:[{icon:'✦',text:'Welcome to the neighborhood. Your first lot is open for business.',time:'JUST NOW'}],upgrades:{lot:0,office:0,staff:0},skills:{bargain:0,mechanic:0,marketing:0},loan:0,debt:0,profit:0,sold:0,view:'overview',filter:'ALL',drive:{active:false,done:false,meters:0,speed:0,lane:0},sound:true});
function loadState(){try{const x=JSON.parse(localStorage.getItem('motorhaus-save'));return x&&x.market&&Array.isArray(x.inventory)?{...defaultState(),...x}:defaultState()}catch{return defaultState()}}
let G=loadState(); let driveFrame=0; let keyState={};
function save(){localStorage.setItem('motorhaus-save',JSON.stringify(G));}
function addActivity(icon,text,color=''){G.activity.unshift({icon,text,color,time:'DAY '+String(G.day).padStart(2,'0')});G.activity=G.activity.slice(0,7);save()}
function toast(msg,type='success'){const el=document.createElement('div');el.className='toast '+type;el.textContent=msg;$('#toast-region').append(el);setTimeout(()=>el.remove(),2900)}
function setView(view){G.view=view;$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#crumb-title').textContent=({overview:'Overview',market:'Car market',workshop:'Workshop',drive:'Test drive',empire:'Empire'})[view];save();render()}
function carSvg(color='#799283',small=false){return `<svg viewBox="0 0 260 110" aria-hidden="true"><ellipse cx="130" cy="92" rx="99" ry="10" fill="#37433b" opacity=".15"/><path d="M37 68 48 53q6-8 22-12l34-8q11-3 21-3h30q16 0 27 12l18 19 13 5q8 3 8 12v8H29v-9q0-7 8-9z" fill="${color}"/><path d="m78 49 29-8q10-3 20-3h24q12 0 20 9l11 12H68z" fill="#dcebe5" opacity=".9"/><path d="m120 39-2 20M157 39l7 20" stroke="#ffffff" stroke-opacity=".6" stroke-width="2"/><path d="M35 72h20M207 72h12" stroke="#fff0c1" stroke-width="5" stroke-linecap="round"/><circle cx="72" cy="83" r="16" fill="#27312c"/><circle cx="72" cy="83" r="8" fill="#b9c3ba"/><circle cx="190" cy="83" r="16" fill="#27312c"/><circle cx="190" cy="83" r="8" fill="#b9c3ba"/><path d="M85 83h91" stroke="#ffffff" stroke-opacity=".2" stroke-width="2"/></svg>`}
function metric(label,value,icon,foot='',positive=false){return `<div class="metric-card"><div class="metric-top"><span>${label}</span><span class="metric-icon">${icon}</span></div><div class="metric-value">${value}</div><div class="metric-foot ${positive?'positive':''}">${foot}</div></div>`}
function pageHead(kicker,title,desc,action=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function topMetric(){return `<div class="metrics">${metric('AVAILABLE CASH',money(G.cash),'◉',G.debt?`Loan balance ${money(G.debt)}`:'Ready to reinvest')}${metric('CARS IN STOCK',G.inventory.length,'▰',`${G.inventory.filter(c=>c.listed).length} listed for sale`)}${metric('REPUTATION',G.rep+' / 100','✳',G.rep>=50?'Trusted local dealer':'Build trust with every deal')}${metric('CARS SOLD',G.sold,'↗',`Day ${String(G.day).padStart(2,'0')} · ${weekdays[(G.day-1)%7]}`)}</div>`}
function activityMarkup(){return G.activity.slice(0,5).map(a=>`<div class="activity"><div class="activity-icon ${a.color||''}">${a.icon}</div><div class="activity-copy">${a.text}</div><div class="activity-time">${a.time}</div></div>`).join('')||'<div class="empty-note">Your business story starts today.</div>'}
function dashboard(){const c=G.inventory.filter(x=>x.listed).slice(0,3);return `${pageHead('MONDAY MORNING · YOUR LOT','Good morning, Jordan.','A fresh day means fresh deals. Your next great flip is out there.','<button class="btn btn-primary" data-action="next-day">⏭ &nbsp;End day</button>')}${topMetric()}<div class="dash-grid"><section class="panel"><div class="panel-head"><div><div class="panel-title">Your dealership</div><div class="panel-sub">A little lot with big ambitions</div></div><button class="text-link" data-view="empire">Manage lot ↗</button></div><div class="lot-scene"><div class="lot-sun"></div><div class="lot-hill hill1"></div><div class="lot-hill hill2"></div><div class="lot-building"><div class="building-roof"></div><div class="building-sign">MOTORHAUS</div><div class="building-window"></div><div class="building-door"></div></div>${G.inventory.slice(0,2).map((car,i)=>`<div class="lot-car car-${i?'b':'a'}">${carSvg(car.color)}</div>`).join('')}<div class="lot-stats"><strong>${G.inventory.length} / ${4+G.upgrades.lot*2}</strong>LOT CAPACITY</div><div class="lot-road"></div><div class="lot-status"><i></i> OPEN FOR BUSINESS</div></div><div class="panel-head"><div><div class="panel-title">Business activity</div><div class="panel-sub">The latest from around the lot</div></div><span class="nav-count">${G.activity.length} NEW</span></div><div class="activity-list">${activityMarkup()}</div></section><div><section class="panel"><div class="panel-head"><div><div class="panel-title">Quick moves</div><div class="panel-sub">Put your next move in motion</div></div></div><div class="quick-actions"><button class="quick-action" data-view="market"><div class="qa-icon">⌕</div><b>Find a car</b><span>Browse 6 deals</span></button><button class="quick-action" data-view="workshop"><div class="qa-icon">⚒</div><b>Fix it up</b><span>Boost your margins</span></button><button class="quick-action" data-view="drive"><div class="qa-icon">↗</div><b>Take a drive</b><span>Win a race bonus</span></button></div></section><section class="panel" style="margin-top:16px"><div class="panel-head"><div><div class="panel-title">On the lot</div><div class="panel-sub">Your current inventory</div></div><button class="text-link" data-view="workshop">View stock ↗</button></div><div class="inventory-strip">${G.inventory.length?G.inventory.slice(0,4).map(c=>`<div class="inventory-row"><div class="mini-car">🚙</div><div><b>${c.name}</b><small>${c.listed?'Listed · '+money(c.ask):'Needs a little love'}</small></div><div class="row-value">${money(c.value)}<small>est. value</small></div></div>`).join(''):'<div class="empty-note">No cars yet. Head to the market and make your first deal.</div>'}</div></section></div></div><div class="bottom-grid"><section class="panel"><div class="panel-head"><div><div class="panel-title">Cars worth a look</div><div class="panel-sub">Hand-picked deals from today’s market</div></div><button class="text-link" data-view="market">Browse all ↗</button></div><div class="inventory-strip">${G.market.slice(0,2).map(c=>`<div class="inventory-row"><div class="mini-car">🚘</div><div><b>${c.name}</b><small>${c.year} · ${c.condition}% condition · ${money(c.value)} market value</small></div><div class="row-value">${money(c.price)}<small>asking</small></div></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><div><div class="panel-title">Today's outlook</div><div class="panel-sub">The market is moving</div></div><span class="metric-icon">☀</span></div><div class="inventory-strip"><div style="font:700 13px 'Space Grotesk';margin:7px 0">${['A good day to make a deal.','Buyers are looking for clean sedans.','The market favors sporty coupes.','Keep an eye out for underpriced SUVs.'][(G.day-1)%4]}</div><div style="font-size:11px;color:#8b958d;line-height:1.6">Clean up stock, set fair prices, and keep your reputation growing. The best dealers know when to hold — and when to sell.</div><button class="btn btn-light" style="margin-top:13px" data-view="market">Visit the car market →</button></div></section></div>`}
function conditionClass(n){return n<45?'low':n<70?'mid':''}
function marketCard(c){let cond=conditionClass(c.condition);return `<article class="market-card"><div class="car-art"><span class="car-badge ${c.risk>22?'risk':c.condition>85?'hot':''}">${c.risk>22?'CHECK HISTORY':c.condition>85?'GREAT FIND':c.source.toUpperCase()}</span>${carSvg(c.color)}<span class="car-price">${money(c.price)}</span></div><div class="market-info"><h3>${c.name}</h3><div class="car-specs"><span>${c.year}</span><span>${c.miles.toLocaleString()} mi</span><span>${c.type}</span></div><div class="car-condition"><span>Condition</span><b>${c.condition}%</b></div><div class="condition-bar"><i class="${cond}" style="width:${c.condition}%"></i></div><div class="market-footer"><span class="seller">Seller · ${c.seller}</span><button class="btn btn-dark" data-action="negotiate" data-id="${c.id}">Make an offer</button></div></div></article>`}
function marketView(){let cars=G.market.filter(c=>G.filter==='ALL'||c.type===G.filter);return `${pageHead('SOURCE · BARGAIN · BUY','The car market','Find an overlooked gem. Every deal starts with the right offer.','<button class="btn btn-outline" data-action="refresh-market">↻ &nbsp;Refresh finds</button>')}<div class="section-row" style="margin-top:0"><div><h2 class="section-title">Today’s finds <span style="color:#9aa39b;font:11px 'DM Sans'">· ${cars.length} vehicles</span></h2></div><div class="market-toolbar"><select class="select-input" id="market-filter"><option value="ALL">All vehicles</option>${['SEDAN','HATCHBACK','SUV','COUPE','SPORT','LUXURY'].map(x=>`<option ${G.filter===x?'selected':''}>${x}</option>`).join('')}</select><span style="font-size:10px;color:#929b94">Fresh daily</span></div></div><div class="car-grid">${cars.length?cars.map(marketCard).join(''):'<div class="market-empty">No cars in this category today. Try another filter.</div>'}</div><div style="margin-top:18px;padding:13px 15px;background:#eff4e8;border-radius:8px;color:#62744f;font-size:11px;line-height:1.6"><b>Dealer note:</b> Ask for a vehicle report before you buy. Some sellers aren’t telling the whole story — and a bad engine can turn a bargain into a burden.</div>`}

