function marketView(){let cars=G.market.filter(c=>G.filter==='ALL'||c.type===G.filter);return `${pageHead('SOURCE · BARGAIN · BUY','The car market','Find an overlooked gem. Every deal starts with the right offer.','<button class="btn btn-outline" data-action="refresh-market">↻ &nbsp;Refresh finds</button>')}<div class="section-row" style="margin-top:0"><div><h2 class="section-title">Today’s finds <span style="color:#9aa39b;font:11px 'DM Sans'">· ${cars.length} vehicles</span></h2></div><div class="market-toolbar"><select class="select-input" id="market-filter"><option value="ALL">All vehicles</option>${['SEDAN','HATCHBACK','SUV','COUPE','SPORT','LUXURY'].map(x=>`<option ${G.filter===x?'selected':''}>${x}</option>`).join('')}</select><span style="font-size:10px;color:#929b94">Fresh daily</span></div></div><div class="car-grid">${cars.length?cars.map(marketCard).join(''):'<div class="market-empty">No cars in this category today. Try another filter.</div>'}</div><div style="margin-top:18px;padding:13px 15px;background:#eff4e8;border-radius:8px;color:#62744f;font-size:11px;line-height:1.6"><b>Dealer note:</b> Ask for a vehicle report before you buy. Some sellers aren’t telling the whole story — and a bad engine can turn a bargain into a burden.</div>`}
function actualValue(c){let base=c.value*(.62+c.condition*.0038);return Math.round(base/100)*100}
function workAction(title,detail,cost,ico,act,disabled=false){return `<button class="work-action" data-action="work" data-work="${act}" ${disabled?'disabled':''}><span class="work-ico">${ico}</span><span class="work-copy"><b>${title}</b><small>${detail}</small></span><span class="work-cost">${cost}</span></button>`}
function workshop(){let car=G.inventory.find(c=>c.id===selectedCarId)||G.inventory[0];if(car)selectedCarId=car.id;return `${pageHead('REPAIR · MODIFY · CUSTOMIZE','The workshop','A little elbow grease can turn a rough trade into a showroom star.')}<div class="workshop-layout"><div><section class="panel"><div class="panel-head"><div><div class="panel-title">${car?car.name:'Your service bay'}</div><div class="panel-sub">${car?`${car.year} · ${car.miles.toLocaleString()} miles · ${car.listed?'Currently listed':'In your inventory'}`:'Select a car from your inventory to get started'}</div></div>${car?`<select class="select-input" id="work-car">${G.inventory.map(c=>`<option value="${c.id}" ${c.id===car.id?'selected':''}>${c.name}</option>`).join('')}</select>`:''}</div><div class="workshop-bay"><div class="bay-grid"></div><div class="bay-caption">SERVICE BAY 01 · ${car?`CONDITION ${car.condition}%`:'EMPTY'}</div>${car?carSvg(car.color):'<div style="position:relative;text-align:center;color:#8f9b90;font-size:12px">⚒<br>Bring a car to the shop</div>'}</div><div class="panel-head"><div><div class="panel-title">Vehicle condition</div><div class="panel-sub">Repairs improve value and buyer confidence</div></div><b style="font:700 14px 'Space Grotesk'">${car?money(actualValue(car)):'—'}</b></div><div style="padding:13px 18px 17px;display:grid;grid-template-columns:repeat(3,1fr);gap:13px">${[['ENGINE',car?.engine],['BODY',car?.body],['CLEAN',car?.clean]].map(([n,v])=>`<div><div style="display:flex;justify-content:space-between;font:9px 'DM Mono';color:#89948a;margin-bottom:6px"><span>${n}</span><b>${v||0}%</b></div><div class="condition-bar"><i class="${conditionClass(v||0)}" style="width:${v||0}%"></i></div></div>`).join('')}</div></section><section class="panel tuning-panel"><div class="panel-head"><div><div class="panel-title">Custom tuning</div><div class="panel-sub">Personalize the ride and lift its asking price</div></div><span class="metric-icon">✳</span></div><div class="tuning-options">${[['◉','Sport rims','Sharper stance · +$700','rims',850],['↕','Street suspension','Tighter handling · +$1,100','suspension',1300],['⚡','Performance kit','More power · +$2,000','performance',2400]].map(([i,n,d,a,cost])=>`<button class="tune-option" data-action="tune" data-tune="${a}" ${!car||car.mods.includes(a)||G.cash<cost?'disabled':''}><span>${i}</span><b>${n}</b><span>${d}</span><em>${car?.mods.includes(a)?'INSTALLED':money(cost)}</em></button>`).join('')}</div></section></div><section class="panel"><div class="panel-head"><div><div class="panel-title">Restoration menu</div><div class="panel-sub">Choose a job for your current vehicle</div></div></div><div class="work-actions">${workAction('Engine service','Restore power and reliability',money(850),'⚙','engine',!car||car.engine>=98||G.cash<850)}${workAction('Bodywork','Repair dents, boost curb appeal',money(650),'✧','body',!car||car.body>=98||G.cash<650)}${workAction('Deep clean','Wash, detail and deodorize',money(180),'◌','clean',!car||car.clean>=98||G.cash<180)}${workAction('Fresh paint','A showroom finish adds value',money(520),'▰','paint',!car||car.mods.includes('paint')||G.cash<520)}</div><div style="margin:0 15px 15px;padding:12px;background:#f5f7f2;border-radius:7px;font-size:10px;color:#89948a;line-height:1.5">${car?`Workshop estimate: <b style="color:#57654d">${money(actualValue(car))}</b> current market value. Complete repairs carefully — a well-presented car earns more.`:'Buy a vehicle first to unlock restoration and tuning.'}</div></section></div>`}
function driveView(){let running=G.drive.active;return `${pageHead('OPEN ROAD · RACING','Take it for a spin','Get a feel for your stock. Stay on the road and bring home a race-day bonus.')}<div class="drive-panel"><div class="drive-canvas-wrap"><canvas id="drive-canvas" class="drive-canvas"></canvas><div class="drive-overlay">${running?'OPEN ROAD CHALLENGE':'MOTORHAUS TEST TRACK'}<span id="drive-speed">${Math.round(G.drive.speed||0)} <small style="font-size:10px">KM/H</small></span></div><div style="position:absolute;right:17px;top:17px;color:#dfe7dd;text-align:right;font:10px 'DM Mono'">DISTANCE<br><b id="drive-distance" style="font-size:15px;color:#c8f169">${Math.floor(G.drive.meters)}m / 550m</b></div></div><aside class="drive-right"><section class="panel drive-stat"><div class="stat-label">CURRENT RIDE</div><strong>${G.inventory[0]?.name||'Dealer Demo GT'}</strong><p>${G.inventory[0]?'Take your newest stock out for a test drive.':'Your dealership demo car is ready to go.'} No fuel costs — just good old-fashioned open road.</p></section><section class="panel drive-stat"><div class="stat-label">RACE DAY BONUS</div><strong style="color:#83a940">+$1,200</strong><p>Drive 550m to complete the track. Avoid the roadwork cones to keep your bonus intact.</p></section><section class="panel controls"><h3>How to drive</h3><div class="key-row"><span class="key">W</span><span class="key">↑</span></div><div class="key-row"><span class="key">A</span><span class="key">←</span><span class="key">S</span><span class="key">→</span><span class="key">D</span></div><div style="font-size:10px;color:#929b94;text-align:center;margin-top:8px">Accelerate · steer around cones · brake</div><div class="drive-buttons"><button class="btn btn-primary" data-action="${running?'pause-drive':'start-drive'}">${running?'Ⅱ &nbsp; Pause':G.drive.done?'↻ &nbsp; Race again':'▶ &nbsp; Start engine'}</button><button class="btn btn-light" data-action="drive-left">←</button><button class="btn btn-light" data-action="drive-right">→</button></div></section></aside></div>`}

