function driveView(){let running=G.drive.active;return `${pageHead('OPEN ROAD · RACING','Take it for a spin','Get a feel for your stock. Stay on the road and bring home a race-day bonus.')}<div class="drive-panel"><div class="drive-canvas-wrap"><canvas id="drive-canvas" class="drive-canvas"></canvas><div class="drive-overlay">${running?'OPEN ROAD CHALLENGE':'MOTORHAUS TEST TRACK'}<span id="drive-speed">${Math.round(G.drive.speed||0)} <small style="font-size:10px">KM/H</small></span></div><div style="position:absolute;right:17px;top:17px;color:#dfe7dd;text-align:right;font:10px 'DM Mono'">DISTANCE<br><b id="drive-distance" style="font-size:15px;color:#c8f169">${Math.floor(G.drive.meters)}m / 550m</b></div></div><aside class="drive-right"><section class="panel drive-stat"><div class="stat-label">CURRENT RIDE</div><strong>${G.inventory[0]?.name||'Dealer Demo GT'}</strong><p>${G.inventory[0]?'Take your newest stock out for a test drive.':'Your dealership demo car is ready to go.'} No fuel costs — just good old-fashioned open road.</p></section><section class="panel drive-stat"><div class="stat-label">RACE DAY BONUS</div><strong style="color:#83a940">+$1,200</strong><p>Drive 550m to complete the track. Avoid the roadwork cones to keep your bonus intact.</p></section><section class="panel controls"><h3>How to drive</h3><div class="key-row"><span class="key">W</span><span class="key">↑</span></div><div class="key-row"><span class="key">A</span><span class="key">←</span><span class="key">S</span><span class="key">→</span><span class="key">D</span></div><div style="font-size:10px;color:#929b94;text-align:center;margin-top:8px">Accelerate · steer around cones · brake</div><div class="drive-buttons"><button class="btn btn-primary" data-action="${running?'pause-drive':'start-drive'}">${running?'Ⅱ &nbsp; Pause':G.drive.done?'↻ &nbsp; Race again':'▶ &nbsp; Start engine'}</button><button class="btn btn-light" data-action="drive-left">←</button><button class="btn btn-light" data-action="drive-right">→</button></div></section></aside></div>`}
function upgradeItem(key,title,desc,cost,ico,max){let level=G.upgrades[key];return `<div class="upgrade-row"><span class="upgrade-icon">${ico}</span><div class="upgrade-copy"><b>${title} <span style="color:#929b94;font-weight:500">· LV ${level}/${max}</span></b><small>${desc}</small></div><span class="upgrade-cost">${level>=max?'MAX':money(cost)}</span><button class="btn btn-outline" data-action="upgrade" data-upgrade="${key}" ${level>=max||G.cash<cost?'disabled':''}>${level>=max?'Done':'Upgrade'}</button></div>`}
function empire(){let skillRows=[['bargain','Smooth talker','Get better prices from sellers.'],['mechanic','Wrench wizard','Repairs cost less and improve more.'],['marketing','Local favorite','More buyers find your listings.']];return `${pageHead('GROW · INVEST · BUILD','Build your empire','Reinvest smart. Grow your lot from a side hustle into the town’s top dealership.')}<div class="empire-grid"><section class="bank-card"><div class="eyebrow">MOTORHAUS BUSINESS ACCOUNT</div><div class="bank-balance">${money(G.cash)}</div><div class="bank-details"><div>OUTSTANDING LOAN<b>${money(G.debt)}</b></div><div>NET PROFIT<b>${money(G.profit)}</b></div><div>WEEKLY TAX<b>8%</b></div></div><div style="display:flex;gap:8px;margin-top:19px;position:relative"><button class="btn btn-primary" data-action="loan" ${G.loan?'disabled':''}>${G.loan?'Loan active':'Take $10,000 loan'}</button><button class="btn btn-outline" data-action="repay" style="background:#ffffff12;color:white;border-color:#ffffff30" ${!G.debt?'disabled':''}>Repay loan</button></div></section><section class="panel"><div class="panel-head"><div><div class="panel-title">Your dealership upgrades</div><div class="panel-sub">A better business starts with the basics</div></div></div><div class="upgrade-list">${upgradeItem('lot','Lot expansion','Two more spaces for your inventory',9500,'▤',3)}${upgradeItem('office','Office makeover','Unlocks a more professional showroom',6800,'⌂',2)}${upgradeItem('staff','Hire a sales assistant','Hands off some daily running costs',7200,'♙',3)}</div></section><section class="panel"><div class="panel-head"><div><div class="panel-title">Dealer skill tree</div><div class="panel-sub">${G.skillPoints} skill point${G.skillPoints===1?'':'s'} ready to spend</div></div><span class="metric-icon">✳</span></div><div class="skills">${skillRows.map(([key,title,desc])=>`<div class="skill-row"><div class="skill-copy"><b>${title}</b><small>${desc} · Level ${G.skills[key]}/3</small></div><div class="skill-pips">${[1,2,3].map(i=>`<i class="${G.skills[key]>=i?'on':''}"></i>`).join('')}</div><button class="btn btn-outline" data-action="skill" data-skill="${key}" ${!G.skillPoints||G.skills[key]>=3?'disabled':''}>+1</button></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><div><div class="panel-title">Recent transactions</div><div class="panel-sub">The books are looking good</div></div></div><div class="history-list">${G.activity.slice(0,5).map(a=>`<div class="history-row"><span>${a.icon} &nbsp;${a.text.replace(/<[^>]+>/g,'').slice(0,42)}</span><b>${a.time}</b></div>`).join('')}</div></section></div><div style="margin-top:16px;padding:13px 15px;border-radius:8px;background:#fff3e7;color:#9c744b;font-size:10px;line-height:1.55"><b>Finance note:</b> Loans are due with 10% interest. A weekly tax of 8% on realized profit is collected every Sunday. Keep some cash in reserve.</div>`}
function render(){const root=$('#view-root');const views={overview:dashboard,market:marketView,workshop,drive:driveView,empire};root.innerHTML=(views[G.view]||dashboard)();$('#day-label').textContent=`${weekdays[(G.day-1)%7]} · DAY ${String(G.day).padStart(2,'0')}`;$('#market-count').textContent=G.market.length;$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===G.view));if(G.view==='drive')setupDriveCanvas();}

