ps">${[1,2,3].map(i=>`<i class="${G.skills[key]>=i?'on':''}"></i>`).join('')}</div><button class="btn btn-outline" data-action="skill" data-skill="${key}" ${!G.skillPoints||G.skills[key]>=3?'disabled':''}>+1</button></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><div><div class="panel-title">Recent transactions</div><div class="panel-sub">The books are looking good</div></div></div><div class="history-list">${G.activity.slice(0,5).map(a=>`<div class="history-row"><span>${a.icon} &nbsp;${a.text.replace(/<[^>]+>/g,'').slice(0,42)}</span><b>${a.time}</b></div>`).join('')}</div></section></div><div style="margin-top:16px;padding:13px 15px;border-radius:8px;background:#fff3e7;color:#9c744b;font-size:10px;line-height:1.55"><b>Finance note:</b> Loans are due with 10% interest. A weekly tax of 8% on realized profit is collected every Sunday. Keep some cash in reserve.</div>`}
+function render(){const root=$('#view-root');const views={overview:dashboard,market:marketView,workshop,drive:driveView,empire};root.innerHTML=(views[G.view]||dashboard)();$('#day-label').textContent=`${weekdays[(G.day-1)%7]} · DAY ${String(G.day).padStart(2,'0')}`;$('#market-count').textContent=G.market.length;$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===G.view));if(G.view==='drive')setupDriveCanvas();}

