function render(){const root=$('#view-root');const views={overview:dashboard,market:marketView,workshop,drive:driveView,empire};root.innerHTML=(views[G.view]||dashboard)();$('#day-label').textContent=`${weekdays[(G.day-1)%7]} · DAY ${String(G.day).padStart(2,'0')}`;$('#market-count').textContent=G.market.length;$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===G.view));if(G.view==='drive')setupDriveCanvas();}
let dealId=null;
function openModal(title,body){$('#modal-root').innerHTML=`<div class="modal-backdrop" data-action="dismiss-modal"><section class="modal"><div class="modal-head"><h2>${title}</h2><button class="modal-close" data-action="dismiss-modal">×</button></div><div class="modal-body">${body}</div></section></div>`;}
function closeModal(){$('#modal-root').innerHTML=''}
function openDeal(id,counter=null){let car=G.market.find(c=>c.id===id);if(!car)return;dealId=id;let min=Math.round(car.price*(.82-G.skills.bargain*.025)/100)*100;openModal(`Make an offer · ${car.name}`,`<div class="seller-line"><span class="seller-face">👨🏻</span><div><b>${car.seller}</b><small>Private seller · ${car.source}</small></div><span style="margin-left:auto;font:11px 'DM Mono';color:#6e7c6d">Asking ${money(car.price)}</span></div><label style="font-size:11px;font-weight:700;color:#667267" for="offer-value">Your offer</label><input id="offer-value" class="offer-price" type="number" min="1" max="${G.cash}" step="100" value="${counter||Math.round(car.price*.84/100)*100}"><div style="font-size:10px;color:#929b94;display:flex;justify-content:space-between"><span>Cash available ${money(G.cash)}</span><span>Typical acceptance ${money(min)}+</span></div>${car.reported?`<div class="report-box"><strong>✓ Appraisal report purchased</strong><br>Engine ${car.engine}% · body ${car.body}% · ${car.risk>25?'⚠ Salvage flag found — seller history does not match.':'No title flags found. Vehicle history looks clean.'}</div>`:`<button class="btn btn-light" style="width:100%;margin-top:13px" data-action="report" data-id="${id}">▤ &nbsp;Request appraisal report · $250</button>`}${counter?`<div class="report-box"><strong>Seller countered at ${money(counter)}.</strong> Adjust your offer to keep the conversation going.</div>`:''}<div class="modal-actions"><button class="btn btn-outline" data-action="dismiss-modal">Maybe later</button><button class="btn btn-primary" data-action="make-offer" data-id="${id}">Send offer →</button></div>`)}
function requestReport(id){let c=G.market.find(x=>x.id===id);if(!c)return;if(c.reported){toast('Appraisal is already in your file.');return}if(G.cash<250){toast('You need $250 for an appraisal report.','warn');return}G.cash-=250;c.reported=true;addActivity('▤',`Paid for an appraisal on the ${c.name}.`,'orange');save();openDeal(id)}
function makeOffer(id){let c=G.market.find(x=>x.id===id);if(!c)return;let input=$('#offer-value'),offer=Math.round(Number(input?.value)||0);if(offer<=0){toast('Enter a valid offer.','warn');return}if(offer>G.cash){toast('That offer is more than your available cash.','warn');return}let floor=Math.round(c.price*(.82-G.skills.bargain*.025)/100)*100;if(offer>=floor){let chance=offer>=c.price?1:clamp(.65+(offer-floor)/Math.max(1,c.price-floor)*.35,.65,.99);if(Math.random()<chance){if(G.inventory.length>=4+G.upgrades.lot*2){toast('Your lot is full. Expand the lot before buying another car.','warn');return}G.cash-=offer;let bought={...c,id:'i'+Date.now().toString(36)+Math.random().toString(36).slice(2,5),buyPrice:offer,source:c.source,listed:false,ask:0,mods:[]};if(!bought.reported&&bought.risk>15&&Math.random()*100<bought.risk){bought.engine=clamp(bought.engine-24,20,100);bought.condition=Math.round((bought.engine+bought.body+bought.clean)/3);addActivity('⚠',`Hidden engine trouble found in your ${bought.name}. Always check the history!`,'red');G.rep=Math.max(0,G.rep-2)}G.inventory.push(bought);G.market=G.market.filter(x=>x.id!==id);G.rep=Math.min(100,G.rep+1);addActivity('↗',`Bought a ${bought.name} for ${money(offer)}.`);closeModal();toast(`${bought.name} is yours. Time to make it shine!`);save();render()}else{let counter=Math.min(c.price,Math.round((floor+offer)/2/100)*100);openDeal(id,counter);toast(`${c.seller} is still negotiating. They countered at ${money(counter)}.`,'warn')}}else{let counter=Math.min(c.price,Math.round((floor+offer)/2/100)*100);openDeal(id,counter);toast(`${c.seller} says that’s too low. Counteroffer: ${money(counter)}.`,'warn')}}
function doWork(type){let c=G.inventory.find(x=>x.id===selectedCarId)||G.inventory[0];if(!c)return;let costs={engine:850,body:650,clean:180,paint:520};let cost=costs[type];cost=Math.round(cost*(1-G.skills.mechanic*.1));if(G.cash<cost){toast('Not enough cash for this job.','warn');return}if(type==='paint'&&c.mods.includes('paint')){toast('This car already has a fresh paint job.','warn');return}G.cash-=cost;if(type==='engine')c.engine=clamp(c.engine+28,0,100);if(type==='body')c.body=clamp(c.body+30,0,100);if(type==='clean')c.clean=clamp(c.clean+42,0,100);if(type==='paint'){c.mods.push('paint');c.color=['#567a72','#bf684f','#7183a3','#d1a34b','#777d73'][Math.floor(Math.random()*5)]}c.condition=Math.round((c.engine+c.body+c.clean)/3);c.listed=false;c.ask=0;addActivity('⚒',`${type==='clean'?'Detailed':type==='paint'?'Repainted':'Repaired'} your ${c.name} for ${money(cost)}.`);save();toast(`${c.name}: ${type} job complete.`);render()}
function tune(type){let c=G.inventory.find(x=>x.id===selectedCarId)||G.inventory[0];if(!c)return;let costs={rims:850,suspension:1300,performance:2400};let cost=Math.round(costs[type]*(1-G.skills.mechanic*.1));if(G.cash<cost||c.mods.includes(type))return;G.cash-=cost;c.mods.push(type);c.value=Math.round(c.value*1.04);if(type==='performance')c.engine=clamp(c.engine+8,0,100);c.condition=Math.round((c.engine+c.body+c.clean)/3);c.listed=false;c.ask=0;addActivity('✳',`Installed ${type==='rims'?'sport rims':type} on your ${c.name} for ${money(cost)}.`);save();toast('Custom upgrade installed. Market value is up!');render()}
function openListing(id){let c=G.inventory.find(x=>x.id===id);if(!c)return;let suggested=Math.round(actualValue(c)*1.12/100)*100;openModal(`List your ${c.name}`,`<div class="report-box">Estimated market value <strong>${money(actualValue(c))}</strong><br>Set a fair price to attract buyers. Overpriced listings may take longer to move.</div><label style="font-size:11px;font-weight:700;color:#667267" for="ask-value">Asking price</label><input id="ask-value" class="offer-price" type="number" min="100" step="100" value="${suggested}"><div class="modal-actions"><button class="btn btn-outline" data-action="dismiss-modal">Cancel</button><button class="btn btn-primary" data-action="list-car" data-id="${id}">List for sale →</button></div>`)}
function listCar(id){let c=G.inventory.find(x=>x.id===id);if(!c)return;let ask=Math.round(Number($('#ask-value')?.value)||0);if(ask<100){toast('Set an asking price of at least $100.','warn');return}c.listed=true;c.ask=ask;closeModal();addActivity('◉',`Listed your ${c.name} for ${money(ask)}.`);save();toast('Your car is on the lot. Let’s find a buyer!');render()}

