/* MOTORHAUS — a tiny dealership sim. Everything is saved locally. */
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const money=n=>'$'+Math.round(n).toLocaleString('en-US'), clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
const weekdays=['MON','TUE','WED','THU','FRI','SAT','SUN'];
const seed=[
 {name:'Cobalt Sprint',year:2017,type:'HATCHBACK',price:7800,value:11200,miles:84200,condition:78,color:'#8aa2a0',seller:'Mia Collins',risk:8,engine:73,body:81,clean:62},
 {name:'Veloce GT',year:2015,type:'COUPE',price:15700,value:22400,miles:61700,condition:72,color:'#c65e4d',seller:'Rico Alvarez',risk:14,engine:70,body:68,clean:74},
 {name:'Northstar LX',year:2019,type:'SUV',price:18600,value:25100,miles:49200,condition:88,color:'#8c927d',seller:'June Park',risk:5,engine:89,body:91,clean:81},
 {name:'Falcon RS',year:2014,type:'SPORT',price:21300,value:30500,miles:72800,condition:63,color:'#d39a43',seller:'Dale Mercer',risk:25,engine:59,body:61,clean:69},
 {name:'Metro 1.6',year:2016,type:'SEDAN',price:6200,value:9700,miles:106300,condition:58,color:'#6379a0',seller:'Nora Bell',risk:11,engine:55,body:67,clean:48},
 {name:'Aurelia S',year:2021,type:'LUXURY',price:36400,value:48200,miles:28300,condition:93,color:'#62776b',seller:'Victor Lane',risk:35,engine:95,body:94,clean:92}
];
const freshMarket=()=>seed.map((t,i)=>({...t,id:'m'+Date.now().toString(36)+Math.random().toString(36).slice(2,5),price:Math.round(t.price*(.94+Math.random()*.13)/100)*100,risk:clamp(t.risk+Math.round(Math.random()*10-5),3,55),reported:false,listed:false,ask:0,mods:[],source:i%2?'Street seller':'City market'}));
const initial=()=>({cash:32000,day:1,rep:12,inventory:[],market:freshMarket(),activity:[{icon:'✦',text:'Welcome to the neighborhood. Your first lot is open for business.',time:'JUST NOW'}],upgrades:{lot:0,office:0,staff:0},skills:{bargain:0,mechanic:0,marketing:0},skillPoints:2,loan:0,debt:0,profit:0,sold:0,view:'overview',filter:'ALL',drive:{active:false,done:false,meters:0,speed:0,lane:0,hits:0}});
function load(){try{const x=JSON.parse(localStorage.getItem('motorhaus-save'));return x&&Array.isArray(x.market)&&Array.isArray(x.inventory)?{...initial(),...x}:initial()}catch{return initial()}}
let G=load(),selectedCarId=G.inventory[0]?.id||null,driveFrame=0,lastDrive=0,cones=[],hitCones=new Set(),keys={};
function save(){try{localStorage.setItem('motorhaus-save',JSON.stringify(G))}catch{}}
function activity(icon,text,color=''){G.activity.unshift({icon,text,color,time:'DAY '+String(G.day).padStart(2,'0')});G.activity=G.activity.slice(0,7);save()}
function toast(msg,type='success'){const region=$('#toast-region');if(!region)return;const el=document.createElement('div');el.className='toast '+type;el.textContent=msg;region.append(el);setTimeout(()=>el.remove(),2900)}
function setView(v){G.view=v;save();render()}
function carSvg(color='#799283'){return `<svg viewBox="0 0 260 110" aria-hidden="true"><ellipse cx="130" cy="92" rx="99" ry="10" fill="#37433b" opacity=".15"/><path d="M37 68 48 53q6-8 22-12l34-8q11-3 21-3h30q16 0 27 12l18 19 13 5q8 3 8 12v8H29v-9q0-7 8-9z" fill="${color}"/><path d="m78 49 29-8q10-3 20-3h24q12 0 20 9l11 12H68z" fill="#dcebe5"/><path d="m120 39-2 20M157 39l7 20" stroke="#fff" stroke-opacity=".6" stroke-width="2"/><circle cx="72" cy="83" r="16" fill="#27312c"/><circle cx="72" cy="83" r="8" fill="#b9c3ba"/><circle cx="190" cy="83" r="16" fill="#27312c"/><circle cx="190" cy="83" r="8" fill="#b9c3ba"/></svg>`}
function metric(label,value,icon,foot=''){return `<div class="metric-card"><div class="metric-top"><span>${label}</span><span class="metric-icon">${icon}</span></div><div class="metric-value">${value}</div><div class="metric-foot">${foot}</div></div>`}
function head(kicker,title,desc,action=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function metrics(){return `<div class="metrics">${metric('AVAILABLE CASH',money(G.cash),'◉',G.debt?'Loan balance '+money(G.debt):'Ready to reinvest')}${metric('CARS IN STOCK',G.inventory.length,'▰',G.inventory.filter(c=>c.listed).length+' listed for sale')}${metric('REPUTATION',G.rep+' / 100','✳','Build trust with every deal')}${metric('CARS SOLD',G.sold,'↗',`Day ${String(G.day).padStart(2,'0')} · ${weekdays[(G.day-1)%7]}`)}</div>`}
function activityList(){return G.activity.slice(0,5).map(a=>`<div class="activity"><div class="activity-icon ${a.color||''}">${a.icon}</div><div class="activity-copy">${a.text}</div><div class="activity-time">${a.time}</div></div>`).join('')||'<div class="empty-note">Your business story starts today.</div>'}
function dashboard(){return `${head('MONDAY MORNING · YOUR LOT','Good morning, Jordan.','A fresh day means fresh deals. Your next great flip is out there.','<button class="btn btn-primary" data-action="next-day">⏭ &nbsp;End day</button>')}${metrics()}<div class="dash-grid"><section class="panel"><div class="panel-head"><div><div class="panel-title">Your dealership</div><div class="panel-sub">A little lot with big ambitions</div></div><button class="text-link" data-view="empire">Manage lot ↗</button></div><div class="lot-scene"><div class="lot-sun"></div><div class="lot-hill hill1"></div><div class="lot-hill hill2"></div><div class="lot-building"><div class="building-roof"></div><div class="building-sign">MOTORHAUS</div><div class="building-window"></div><div class="building-door"></div></div>${G.inventory.slice(0,2).map((c,i)=>`<div class="lot-car car-${i?'b':'a'}">${carSvg(c.color)}</div>`).join('')}<div class="lot-stats"><strong>${G.inventory.length} / ${4+G.upgrades.lot*2}</strong>LOT CAPACITY</div><div class="lot-road"></div><div class="lot-status"><i></i> OPEN FOR BUSINESS</div></div><div class="panel-head"><div><div class="panel-title">Business activity</div><div class="panel-sub">The latest from around the lot</div></div></div><div class="activity-list">${activityList()}</div></section><div><section class="panel"><div class="panel-head"><div><div class="panel-title">Quick moves</div><div class="panel-sub">Put your next move in motion</div></div></div><div class="quick-actions"><button class="quick-action" data-view="market"><div class="qa-icon">⌕</div><b>Find a car</b><span>Browse ${G.market.length} deals</span></button><button class="quick-action" data-view="workshop"><div class="qa-icon">⚒</div><b>Fix it up</b><span>Boost your margins</span></button><button class="quick-action" data-view="drive"><div class="qa-icon">↗</div><b>Take a drive</b><span>Win a race bonus</span></button></div></section><section class="panel"><div class="panel-head"><div><div class="panel-title">Your listings</div><div class="panel-sub">Cars on the showroom floor</div></div></div>${G.inventory.filter(c=>c.listed).slice(0,3).map(c=>`<div class="listing-row">${c.name}<b>${money(c.ask)}</b></div>`).join('')||'<div class="empty-note">No cars listed yet. Find a deal and list it for sale.</div>'}</section></div></div>`}
function conditionClass(n){return n<45?'low':n<70?'mid':''}
function marketCard(c){return `<article class="market-card"><div class="car-art"><span class="car-badge ${c.risk>22?'risk':c.condition>85?'hot':''}">${c.risk>22?'CHECK HISTORY':c.condition>85?'GREAT FIND':c.source.toUpperCase()}</span>${carSvg(c.color)}<span class="car-price">${money(c.price)}</span></div><div class="market-info"><h3>${c.name}</h3><div class="car-specs"><span>${c.year}</span><span>${c.miles.toLocaleString()} mi</span><span>${c.type}</span></div><div class="car-condition"><span>Condition</span><b>${c.condition}%</b></div><div class="condition-bar"><i class="${conditionClass(c.condition)}" style="width:${c.condition}%"></i></div><div class="market-footer"><span class="seller">Seller · ${c.seller}</span><button class="btn btn-dark" data-action="negotiate" data-id="${c.id}">Make an offer</button></div></div></article>`}
function market(){const cars=G.market.filter(c=>G.filter==='ALL'||c.type===G.filter);return `${head('SOURCE · BARGAIN · BUY','The car market','Find an overlooked gem. Every deal starts with the right offer.','<button class="btn btn-outline" data-action="refresh-market">↻ &nbsp;Refresh finds</button>')}<div class="section-row" style="margin-top:0"><div><h2 class="section-title">Today’s finds <span style="color:#9aa39b;font:11px 'DM Sans'">· ${cars.length} vehicles</span></h2></div><div class="market-toolbar"><select class="select-input" id="market-filter"><option value="ALL">All vehicles</option>${['SEDAN','HATCHBACK','SUV','COUPE','SPORT','LUXURY'].map(x=>`<option value="${x}" ${G.filter===x?'selected':''}>${x}</option>`).join('')}</select><span style="font-size:10px;color:#929b94">Fresh daily</span></div></div><div class="car-grid">${cars.map(marketCard).join('')||'<div class="market-empty">No cars in this category today. Try another filter.</div>'}</div><div class="dealer-note"><b>Dealer note:</b> Ask for a vehicle report before you buy. Some sellers aren’t telling the whole story — and a bad engine can turn a bargain into a burden.</div>`}
function actualValue(c){return Math.round(c.value*(.62+c.condition*.0038)/100)*100}

