iv class="tuning-options">${[['◉','Sport rims','Sharper stance · +$700','rims',850],['↕','Street suspension','Tighter handling · +$1,100','suspension',1300],['⚡','Performance kit','More power · +$2,000','performance',2400]].map(([ico,n,d,t,cost])=>`<button class="tune-option" data-action="tune" data-tune="${t}" ${!c||c.mods.includes(t)||G.cash<cost?'disabled':''}><span>${ico}</span><b>${n}</b><span>${d}</span><em>${c?.mods.includes(t)?'INSTALLED':money(cost)}</em></button>`).join('')}</div></section></div><section class="panel"><div class="panel-head"><div><div class="panel-title">Restoration menu</div><div class="panel-sub">Choose a job for your current vehicle</div></div></div><div class="work-actions">${action('Engine service','Restore power and reliability',850,'engine',!c||c.engine>=98||G.cash<850)}${action('Bodywork','Repair dents, boost curb appeal',650,'body',!c||c.body>=98||G.cash<650)}${action('Deep clean','Make it showroom ready',180,'clean',!c||c.clean>=98||G.cash<180)}${action('Fresh paint','Give it a new look',520,'paint',!c||c.mods.includes('paint')||G.cash<520)}</div><div class="panel-head"><div><div class="panel-title">Inventory</div><div class="panel-sub">${G.inventory.length} vehicles on your lot</div></div></div>${G.inventory.map(x=>`<div class="inventory-row"><span>${x.name}</span><b>${x.condition}%</b><button class="btn btn-outline" data-action="select-car" data-id="${x.id}">Service</button><button class="btn btn-primary" data-action="list" data-id="${x.id}">${x.listed?'Update listing':'List for sale'}</button></div>`).join('')||'<div class="empty-note">Buy your first vehicle at the market.</div>'}</section></div>`}
